import{_ as a,o,c as t,j as i,a as r,G as n,aa as p,B as d}from"./chunks/framework.VLjJFeoF.js";const f=JSON.parse('{"title":"前端工程化","description":"","frontmatter":{},"headers":[],"relativePath":"docs/interview/build/engineering.md","filePath":"docs/interview/build/engineering.md","lastUpdated":1769531044000}'),u={name:"docs/interview/build/engineering.md"};function s(c,l,h,m,b,S){const e=d("ArticleMetadata");return o(),t("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1769531044000"},[l[0]||(l[0]=i("h1",{id:"前端工程化",tabindex:"-1"},[r("前端工程化 "),i("a",{class:"header-anchor",href:"#前端工程化","aria-label":'Permalink to "前端工程化"'},"​")],-1)),n(e,{article:{}}),l[1]||(l[1]=p('<h2 id="聊一聊前端工程化" tabindex="-1">聊一聊前端工程化 <a class="header-anchor" href="#聊一聊前端工程化" aria-label="Permalink to &quot;聊一聊前端工程化&quot;">​</a></h2><p>服务对象就是前端开发，涉及整个研发流程；通过工具、规范、流程 等系统性的解决研发中的问题，提高研发效率和质量。</p><ul><li>创建项目：比如脚手架、模板、组件库</li><li>开发/联调：Mock工具</li><li>构建、测试、部署：CICD、自动化测试、CodeReview</li><li>质量：监控系统</li></ul><h2 id="前端基建可以做哪些" tabindex="-1">前端基建可以做哪些 <a class="header-anchor" href="#前端基建可以做哪些" aria-label="Permalink to &quot;前端基建可以做哪些&quot;">​</a></h2><p>目的：提高研发效能，服务业务开发，更好地支撑业务发展。</p><p>基础/初期基建：脚手架、组件库</p><p>方向：</p><ul><li><p>规范和文档建设</p><ul><li>代码规范、git规范、流程规范</li><li>业务文档、技术文档、分享沉淀</li></ul></li><li><p>脚手架</p><ul><li>页面模板</li></ul></li><li><p>联调工具</p></li><li><p>CICD</p></li><li><p>监控体系</p></li><li><p>微前端</p></li><li><p>低代码</p></li><li><p>团队建设、技术分享、技术输出</p></li></ul><p>实践：</p><ul><li>要识别问题，进行复盘和归类，用工程化的手段去解决</li><li>提高技术氛围、CR、技术分享、选择合适的人选</li><li>要向上获取授权，要结果导向，有数据支撑</li></ul><h2 id="脚手架要考虑哪些" tabindex="-1">脚手架要考虑哪些 <a class="header-anchor" href="#脚手架要考虑哪些" aria-label="Permalink to &quot;脚手架要考虑哪些&quot;">​</a></h2><p>通过命令行的交互，选择所需要的配置与集成，可快速完成初始项目的创建。</p><p>CLI(Command Line Interface)+模板</p><p>还要考虑：文件结构、http请求封装、组件库、工具方法、eslint、prettier、脚本命令、构建流程</p><p>好处：</p><ul><li>快速初始化项目，减少重复工作</li><li>统一代码风格</li><li>降低上手成本，更专注于业务开发</li></ul><h2 id="说一下模块化方案" tabindex="-1">说一下模块化方案 <a class="header-anchor" href="#说一下模块化方案" aria-label="Permalink to &quot;说一下模块化方案&quot;">​</a></h2><p>模块化是为了解决代码的复用和组织问题，可以说有了模块化才让前端有了工程的概念，模块化要解决两大问题 代码隔离和依赖管理，从node.js最早发布的commonjs 到浏览器端的 AMD,CMD 规范以及兼容的 UMD 规范，再到现在主流的ES Module规范。</p><ul><li>AMD CMD 都是为了解决浏览器端的模块化问题，区别就是代码执行时机不同，CMD是懒执行。</li><li>UMD就是兼容CommonJS ，AMD 以及全局变量来加载模块。</li><li>ESM是在语言标准的层面上实现了模块功能，Node.js也支持（13版本后，.mjs 或者声明 type:module），</li></ul><p><strong>CJS和ESM的区别</strong>：</p><ul><li>CommonJS 模块是运行时加载，ES6 模块是编译时输出接口。</li><li>CommonJS 模块输出的是一个值的拷贝，ES6 模块输出的是值的引用。</li><li>CommonJS 模块的顶层<code>this</code>指向当前模块的输出<code>module.exports</code>；ES6 模块之中，顶层的<code>this</code>指向<code>undefined</code>。</li><li>CommonJS 模块的<code>require()</code>是同步加载模块，动态<code>import</code>是异步加载，有一个独立的模块依赖的解析阶段。</li><li>ESM生态在逐渐发展，随着 vite等工具的流行，no-bundle 也在逐渐推广，ESM取代CJS是大势所趋。</li></ul><h2 id="介绍一下vite-相比webpack的优缺点" tabindex="-1">介绍一下vite 相比webpack的优缺点 <a class="header-anchor" href="#介绍一下vite-相比webpack的优缺点" aria-label="Permalink to &quot;介绍一下vite 相比webpack的优缺点&quot;">​</a></h2><ul><li>vite把自己定义为工具链，可以开箱即用，配置简单，生态也再不断完善，ESM，bundle-less 也是大势所趋。</li><li>基于 ESM 和 ESBuild 的Dev Server，冷启动速度快，按需编译</li><li>webpack 兼容性好，生态完善</li></ul><h2 id="说一下rollup" tabindex="-1">说一下Rollup <a class="header-anchor" href="#说一下rollup" aria-label="Permalink to &quot;说一下Rollup&quot;">​</a></h2><p>rollup是一款打包构建工具，通常用来构建一些库，比如Vue等都是用rollup构建的。是基于ESM的打包器，支持tree-shaking，scope hoisting等特性。 可以输出多种模块规范的代码，也有丰富的插件。Rollup 插件基本就是各种 Hook 函数的组合。</p><p>Rollup 的打包过程中，会定义一套完整的构建生命周期，从开始打包到产物输出，中途会经历一些<strong>标志性的阶段</strong>，并且在不同阶段会自动执行对应的插件钩子函数(Hook)。对 Rollup 插件来讲，最重要的部分是钩子函数，一方面它定义了插件的执行逻辑，也就是&quot;做什么&quot;；另一方面也声明了插件的作用阶段，即&quot;什么时候做&quot;，这与 Rollup 本身的构建生命周期息息相关。</p><h2 id="ast和babel" tabindex="-1">AST和Babel <a class="header-anchor" href="#ast和babel" aria-label="Permalink to &quot;AST和Babel&quot;">​</a></h2><ul><li>抽象语法树：对代码的一种抽象表示，是树形结构。</li><li>应用：代码高亮，JS转义，代码压缩，ESLint，Prettier等</li><li>babel 编译 ES5 的过程：parse（解析代码生成AST）、transform（通过 traverse 遍历 AST 进行处理转换）、generator (生成代码)</li></ul><h2 id="包管理工具" tabindex="-1">包管理工具 <a class="header-anchor" href="#包管理工具" aria-label="Permalink to &quot;包管理工具&quot;">​</a></h2><ul><li>pnpm <ul><li>硬链接可以避免重复安装，节省空间，速度更快</li><li>解决问题：幽灵依赖和分身依赖（相同依赖不同版本）</li><li>硬链接： 保证相同的包不会被重新新增，磁盘的目录下，inode相同，数据共享，节省内存，修改会同步更改</li><li>软链接（符号链接）：相当于快捷方式，node_modules 里的软链接到对应的.pnpm下的依赖，解决幽灵依赖问题</li><li>符号链接是指向目标路径的链接，而硬链接则是指向目标数据对象的链接</li><li>自带monorepo</li></ul></li></ul><h2 id="cicd" tabindex="-1">CICD <a class="header-anchor" href="#cicd" aria-label="Permalink to &quot;CICD&quot;">​</a></h2><ul><li>CI：持续集成，拉代码，测试和构建，构建出成果物</li><li>CD: <ul><li>持续交付：将已验证的代码发布到存储库</li><li>持续部署：部署到生产环境</li></ul></li></ul><p>好处：流程自动化，减少人为失误，提高迭代效率。</p><p>演化过程：</p><ul><li>前后端不分离，依赖后端</li><li>使用nginx管理前端静态文件</li><li>使用docker，优势： <ul><li>部署高效，易于迁移</li><li>环境一致性</li><li>易于CICD</li><li>便于部署回滚</li></ul></li></ul><p>一些实践：</p><ul><li>安装依赖：使用 npm ci 代替 npm i ，提升速度至少30%</li><li>部署优化 <ul><li>springboot - tomcat</li><li>maven - shell</li></ul></li></ul>',37))])}const q=a(u,[["render",s]]);export{f as __pageData,q as default};
